import http from 'node:http';import fs from 'node:fs';import {resolve} from 'node:path';import{spawn}from'node:child_process';import{createHash}from'node:crypto';
const root=resolve(import.meta.dirname,'..');const deployment=process.argv[2];if(!/^https:\/\/dinospace-[a-z0-9]+-memas-projects-23a0001d\.vercel\.app$/.test(deployment||''))throw Error('An exact candidate deployment URL is required');
const file=resolve(root,'docs/game-delivery-20261019/batch1/approved-provider-qa/storybook-live-proxy-status.json');if(fs.existsSync(file))throw Error('Approved live job already exists; never restart it automatically');
const job={deployment,providerCap:23,priorLocalUnauthenticatedAttempts:1,used:1,reserved:0,requests:[],startedAt:new Date().toISOString(),status:'ready'};const save=()=>fs.writeFileSync(file,JSON.stringify(job,null,2)+'\n');
const call=async(stage,body,session,signal)=>new Promise((resolveResult,reject)=>{
 const args=['curl','/api/story/'+stage,'--deployment',deployment,'--scope','memas-projects-23a0001d','--','--silent','--show-error','--include','--retry','0','--max-time','125','--request','POST','--header','Origin: https://dinospace-eight.vercel.app','--header','Content-Type: application/json','--data-binary','@-'];if(session)args.push('--header','X-Amari-Story-Session: '+session);
 const proc=spawn('vercel',args,{cwd:root,stdio:['pipe','pipe','pipe'],signal});const chunks=[];let size=0;proc.stdout.on('data',c=>{size+=c.length;if(size>24000000)proc.kill('SIGTERM');else chunks.push(c)});proc.stderr.on('data',()=>{});proc.on('error',reject);proc.on('exit',code=>{if(code!==0)return reject(new Error('Authenticated deployment request failed, exit '+code));const buffer=Buffer.concat(chunks);let offset=0,status,headers;
 while(true){const end=buffer.indexOf('\r\n\r\n',offset);if(end<0)return reject(new Error('Missing HTTP response headers'));const text=buffer.subarray(offset,end).toString('utf8');const match=text.match(/HTTP\/[\d.]+\s+(\d+)/);if(!match)return reject(new Error('Invalid HTTP response prefix'));status=Number(match[1]);headers=Object.fromEntries(text.split('\r\n').slice(1).filter(l=>l.includes(':')).map(l=>{const p=l.indexOf(':');return[l.slice(0,p).toLowerCase(),l.slice(p+1).trim()]}));offset=end+4;if(buffer.subarray(offset,offset+5).toString()==='HTTP/')continue;break}
 resolveResult({status,headers,body:buffer.subarray(offset)});
 });proc.stdin.end(body)
});
http.createServer(async(req,res)=>{
 const origin=req.headers.origin||'http://127.0.0.1:5180';res.setHeader('Access-Control-Allow-Origin',origin);res.setHeader('Access-Control-Allow-Headers','Content-Type, X-Amari-Story-Session');res.setHeader('Access-Control-Allow-Methods','POST, OPTIONS');res.setHeader('Access-Control-Expose-Headers','X-Amari-Image-Provider, X-Amari-Image-Model, X-Amari-Voice-Provider, X-Amari-Provider-Attempts');
 if(req.method==='OPTIONS'){res.writeHead(204);res.end();return}
 const stage=new URL(req.url,'http://127.0.0.1:5181').pathname.split('/').at(-1);const limits={session:2,outline:1,image:7,narration:7};const maximum={session:0,outline:2,image:2,narration:1}[stage];if(!(stage in limits)||req.method!=='POST'){res.writeHead(404);res.end();return}
 if(job.requests.filter(x=>x.stage===stage).length>=limits[stage]||job.used+job.reserved+maximum>23){res.writeHead(409,{'Content-Type':'application/json'});res.end(JSON.stringify({error:'Approved QA cap reached; no automatic retry is allowed.'}));return}
 let row;try{const chunks=[];let size=0;for await(const c of req){size+=c.length;if(size>12000000)throw Error('Request too large');chunks.push(c)}const body=Buffer.concat(chunks);if(stage==='outline'){const data=JSON.parse(body);if(data.ageBand!=='3-4'||!data.topic?.startsWith('Synthetic QA 2026-10-19:'))throw Error('Not the approved six-page synthetic QA input')}
 row={stage,startedAt:new Date().toISOString(),reserved:maximum};job.requests.push(row);job.reserved+=maximum;job.status='running';save();
 const controller=new AbortController();res.once('close',()=>{if(!res.writableEnded)controller.abort()});const response=await call(stage,body,req.headers['x-amari-story-session'],controller.signal);const count=stage==='session'?0:Number(response.headers['x-amari-provider-attempts']);if(!Number.isInteger(count)||count<0||count>maximum)throw Error('Provider attempt receipt missing or invalid');job.reserved-=maximum;job.used+=count;row.providerAttempts=count;row.httpStatus=response.status;row.bytes=response.body.length;row.finishedAt=new Date().toISOString();if(stage!=='session')row.sha256=createHash('sha256').update(response.body).digest('hex');row.model=response.headers['x-amari-image-model']||null;save();
 for(const header of ['content-type','content-encoding','x-amari-image-provider','x-amari-image-model','x-amari-voice-provider','x-amari-provider-attempts'])if(response.headers[header])res.setHeader(header,response.headers[header]);res.writeHead(response.status);res.end(response.body);
 }catch(error){job.status='stopped';job.error=error.message;if(row){row.error=error.message;row.finishedAt=new Date().toISOString()}save();res.writeHead(502,{'Content-Type':'application/json'});res.end(JSON.stringify({error:'The bounded QA request stopped; no automatic retry will be made.'}))}
}).listen(5181,'127.0.0.1',()=>{save();console.log(JSON.stringify({proxy:'http://127.0.0.1:5181',deployment,remainingProviderBudget:22,automaticRetries:false}))});
